import { HttpClient } from '@angular/common/http';
import { Component } from '@angular/core';
import { NgForm } from '@angular/forms';
import { Router } from '@angular/router';

@Component({
  selector: 'app-signup-page',
  templateUrl: './signup.component.html',
  styleUrls: ['./signup.component.scss']
})
export class SignupComponent {
  user = {
    name: '',
    email: '',
    password: '',
    role: ''
  };
constructor(private http: HttpClient, private router: Router) {}

  onSignup() {
     const { name, email, password, role } = this.user;

    if (name && email && password && role) {
      this.http.post('http://localhost:8080/api/auth/signup', this.user).subscribe({
        next: (res: any) => {
          console.log('Signup success:', res);

          // Navigate to appropriate dashboard
          switch (role.toLowerCase()) {
            case 'admin':
              this.router.navigate(['/admin-dashboard']);
              break;
            case 'seller':
              this.router.navigate(['/seller-dashboard']);
              break;
            case 'customer':
              this.router.navigate(['/customer-dashboard']);
              break;
            default:
              this.router.navigate(['/']);
              break;
          }
        },
        error: (err: any) => {
          console.error('Signup error:', err);
          alert('Signup failed. Please try again.');
        }
      });
    } else {
      alert("Please fill out all fields.");
    }
  }
}
<div class="container mt-5 mb-5">
  <div class="row justify-content-center">
    <div class="col-md-6">
      <div class="card shadow-lg p-4">
        <h2 class="text-center mb-4">Sign Up</h2>
        <form #signupForm="ngForm" (ngSubmit)="onSignup()">

          <div class="mb-3">
            <label for="name" class="form-label">Full Name</label>
            <input
              type="text"
              id="name"
              name="name"
              class="form-control"
              required
              [(ngModel)]="user.name"
            />
          </div>

          <div class="mb-3">
            <label for="email" class="form-label">Email</label>
            <input
              type="email"
              id="email"
              name="email"
              class="form-control"
              required
              [(ngModel)]="user.email"
            />
          </div>

          <div class="mb-3">
            <label for="password" class="form-label">Password</label>
            <input
              type="password"
              id="password"
              name="password"
              class="form-control"
              required
              [(ngModel)]="user.password"
            />
          </div>

          <div class="mb-3">
            <label for="role" class="form-label">Role</label>
            <select
              id="role"
              name="role"
              class="form-select"
              required
              [(ngModel)]="user.role"
            >
              <option value="" disabled selected>Select a role</option>
              <option value="user">Customer</option>
              <option value="admin">Admin</option>
            </select>
          </div>

          <button type="submit" class="btn btn-primary w-100">Sign Up</button>

          <div class="text-center mt-3">
            Already have an account?
            <a routerLink="/login" class="text-decoration-none">Login here</a>
          </div>
        </form>
      </div>
    </div>
  </div>
</div>
